package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
final class DashboardsBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  var f=ReportSchedulesAcceptance.seed(h.store);String report=f.get("report").toString();try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","DashboardBrowserReader","role","reader","password",WorkflowSupport.PASSWORD));db.connection.commit();}String group=DashboardsAcceptance.group(h.store,"Service leadership","DashboardBrowserReader");
  try(var p=Playwright.create();var browser=p.chromium().launch();var admin=browser.newContext();var viewer=browser.newContext()){
   var page=admin.newPage();h.login(page,"admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Dashboards").setExact(true)).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Create dashboard").setExact(true)).press("Enter");page.getByLabel("Dashboard name").fill("Service outcomes <script>");page.getByLabel("Audience").selectOption("groups");page.getByLabel("Viewer team 1",new Page.GetByLabelOptions().setExact(true)).selectOption(group);page.getByLabel("Report 1",new Page.GetByLabelOptions().setExact(true)).selectOption(report);page.getByLabel("Metric 1",new Page.GetByLabelOptions().setExact(true)).selectOption("average");page.getByLabel("Report 2",new Page.GetByLabelOptions().setExact(true)).selectOption(report);page.getByLabel("Metric 2",new Page.GetByLabelOptions().setExact(true)).selectOption("sum");ReleaseBrowserAcceptance.accessible(page);ServiceOutagesBrowserAcceptance.click(page,"Save dashboard");String path=new java.net.URI(page.url()).getPath(),id=path.substring(path.lastIndexOf('/')+1);assertThat(page.locator("[data-widget='0'] strong")).hasText("50");assertThat(page.locator("[data-widget='1'] strong")).hasText("100");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/dashboard-owner-light.png")).setFullPage(true));
   var reader=viewer.newPage();h.login(reader,"DashboardBrowserReader");reader.navigate(h.base()+path);assertThat(reader.locator("[data-widget='0'] strong")).hasText("10");assertThat(reader.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Edit dashboard").setExact(true))).hasCount(0);ServiceOutagesBrowserAcceptance.click(reader,"Dark mode");reader.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(reader);assertEquals(false,reader.evaluate("document.documentElement.scrollWidth>window.innerWidth"));reader.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/dashboard-team-dark.png")).setFullPage(true));try(var db=h.store.open()){PlatformFoundationTest.bind(db);GroupMembers.change(db,group,db.viewerId,map("user_id",RecordAccess.owner(db,"DashboardBrowserReader")),false);db.connection.commit();}reader.reload();assertThat(reader.locator("main")).containsText("Dashboard not found");
   page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Edit dashboard").setExact(true)).press("Enter");page.getByLabel("Audience").selectOption("workspace");page.getByLabel("Viewer team 1",new Page.GetByLabelOptions().setExact(true)).selectOption("");page.getByLabel("Metric 1",new Page.GetByLabelOptions().setExact(true)).selectOption("max");page.getByLabel("Metric 2",new Page.GetByLabelOptions().setExact(true)).selectOption("count");ServiceOutagesBrowserAcceptance.click(page,"Save dashboard");reader.navigate(h.base()+path);assertThat(reader.locator("[data-widget='0'] strong")).hasText("10");assertThat(reader.locator("[data-widget='1'] strong")).hasText("1");try(var db=h.store.open()){PlatformFoundationTest.bind(db);SavedReports.remove(db,db.viewerId,report);db.connection.commit();}reader.reload();assertThat(reader.locator("main")).containsText("Report unavailable");assertThat(reader.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Open source report"))).hasCount(0);ReleaseBrowserAcceptance.accessible(reader);reader.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/dashboard-unavailable-dark.png")).setFullPage(true));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Edit dashboard").setExact(true)).press("Enter");ServiceOutagesBrowserAcceptance.click(page,"Delete dashboard");assertThat(page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Service outcomes <script>").setExact(true))).hasCount(0);try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_dashboard WHERE dashboard_id=?",id));}
  }
 }
}
